SELECT COUNT(1)
FROM salesperson_task
WHERE company_id = #{companyId}
	AND COALESCE(use_all_distributor, 0) = 1
	AND task_type = #{taskType}
	AND (
		( start_time <= #{startTime} AND end_time >= #{startTime} )
		OR
		( start_time <= #{endTime} AND end_time >= #{endTime} )
	)

	AND task_id != #{excludeTaskId}

SELECT COUNT(1)
FROM salesperson_task st
LEFT JOIN salesperson_task_rel_distributor strd ON st.task_id = strd.task_id
WHERE st.company_id = #{companyId}
	AND COALESCE(st.use_all_distributor, 0) = 0
	AND st.task_type = #{taskType}
	AND (
		( st.start_time <= #{startTime} AND st.end_time >= #{startTime} )
		OR
		( st.start_time <= #{endTime} AND st.end_time >= #{endTime} )
	)

	AND strd.distributor_id IN

		#{id}



	AND st.task_id != #{excludeTaskId}
